cypress_script:
describe('HTTP Status Codes Page', () => {
  it('should navigate to 200 status code page', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.get('a').contains('200').click();
    cy.url().should('include', '/status_codes/200');
  });
  it('should not navigate for invalid status code', () => {
    cy.visit('https://the-internet.herokuapp.com/status_codes');
    cy.get('a').contains('404').click();
    cy.url().should('include', '/status_codes/404');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('HTTP Status Codes Page', () => {
  test('should navigate to 200 status code page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await page.click('a:has-text("200")');
    expect(page.url()).toContain('/status_codes/200');
  });
  test('should not navigate for invalid status code', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
    await page.click('a:has-text("404")');
    expect(page.url()).toContain('/status_codes/404');
  });
});
